	case DATA_FORMAT_ASTC_12x10_UNORM_BLOCK:
	case DATA_FORMAT_ASTC_12x10_SRGB_BLOCK:
	case DATA_FORMAT_ASTC_12x10_SFLOAT_BLOCK:
